import java.io.DataOutputStream;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

/**
 * Bounded, persisted next-execution safety state for one logical expression's physical alternatives.
 *
 * <p>
 * The store deliberately does not own statistical sample counts. One completed execution changes at most one lifecycle
 * record, regardless of how many opens or probes that execution contained.
 */
final class PlanLifecycleStore {

	private static final int MAX_PERSISTED_ENTRIES_MULTIPLIER = 4;

	enum State {
		MONITORING,
		APPLYING,
		BLOCKED,
		QUARANTINED,
		STALE
	}

	record ObjectiveEnvelope(double lower, double point, double upper) {
		ObjectiveEnvelope {
			if (!finiteNonNegative(lower) || !finiteNonNegative(point) || !finiteNonNegative(upper)
					|| lower > point || point > upper) {
				throw new IllegalArgumentException("objective envelope must be finite, non-negative, and ordered");
			}
		}

		private void writeTo(DataOutputStream out) throws IOException {
			out.writeDouble(lower);
			out.writeDouble(point);
			out.writeDouble(upper);
		}

		private static ObjectiveEnvelope readFrom(DataInputStream in) throws IOException {
			try {
				return new ObjectiveEnvelope(in.readDouble(), in.readDouble(), in.readDouble());
			} catch (IllegalArgumentException malformed) {
				throw new IOException("Invalid lifecycle objective envelope", malformed);
			}
		}
	}

	record Decision(State state, boolean eligible, boolean lastGood, double comparisonCost,
			ObjectiveEnvelope envelope, String lastGoodPhysicalDigest, double lastGoodVerifiedUpper,
			double regressionLimit, String reason) {
	}

	private final int maximumEntries;
	private final LinkedHashMap<LifecycleKey, Entry> entries = new LinkedHashMap<>();
	private final LinkedHashMap<GroupKey, GroupCell> groups = new LinkedHashMap<>();
	private long revision;
	private long generation;

	PlanLifecycleStore(int maximumEntries) {
		if (maximumEntries <= 0) {
			throw new IllegalArgumentException("lifecycle capacity must be positive");
		}
		this.maximumEntries = maximumEntries;
	}

	/** Direct lifecycle destination leased for one precompiled query execution. */
	static final class ResolvedEntry {
		private final LifecycleKey key;
		private final Entry entry;
		private final GroupCell group;
		private final long generation;
		private boolean released;

		private ResolvedEntry(LifecycleKey key, Entry entry, GroupCell group, long generation) {
			this.key = key;
			this.entry = entry;
			this.group = group;
			this.generation = generation;
		}
	}

	synchronized ResolvedEntry resolve(LogicalLearningKey logicalKey, PhysicalResidualKey physicalKey,
			LearningApplicability applicability, ObjectiveEnvelope planned) {
		LifecycleKey key = new LifecycleKey(logicalKey, physicalKey, applicability);
		Entry entry = entries.get(key);
		if (entry == null) {
			entry = admit(key, planned);
		}
		if (entry == null) {
			return null;
		}
		entry.planned = planned;
		entry.leases++;
		GroupCell group = groups.computeIfAbsent(key.group(), ignored -> new GroupCell());
		return new ResolvedEntry(key, entry, group, generation);
	}

	synchronized boolean observeResolved(ResolvedEntry resolved, double actualObjective,
			boolean semanticallyValid, double regressionLimit, long epoch) {
		if (resolved == null || resolved.released || resolved.generation != generation) {
			return false;
		}
		return observe(resolved.key, resolved.entry, resolved.group, actualObjective, semanticallyValid,
				regressionLimit, epoch);
	}

	synchronized void release(ResolvedEntry resolved) {
		if (resolved == null || resolved.released) {
			return;
		}
		resolved.released = true;
		if (resolved.entry.leases > 0) {
			resolved.entry.leases--;
		}
	}

	synchronized Decision decision(LogicalLearningKey logicalKey, PhysicalResidualKey physicalKey,
			LearningApplicability applicability, ObjectiveEnvelope envelope, boolean enforce) {
		LifecycleKey key = new LifecycleKey(logicalKey, physicalKey, applicability);
		Entry entry = entries.get(key);
		if (entry == null) {
			entry = admit(key, envelope);
		}
		if (entry == null) {
			return new Decision(State.MONITORING, true, false,
					enforce ? envelope.upper() : envelope.point(), envelope, "", Double.NaN,
					Double.POSITIVE_INFINITY,
					"monitoring-capacity-protected");
		}
		entry.planned = envelope;
		if (entry.state == State.STALE) {
			transition(entry, State.MONITORING, "epoch-change-monitoring");
		}
		GroupKey group = key.group();
		GroupCell groupCell = groups.computeIfAbsent(group, ignored -> new GroupCell());
		LifecycleKey lastGoodKey = groupCell.lastGoodKey;
		Entry lastGood = groupCell.lastGood;
		if (lastGood == null && lastGoodKey != null) {
			groupCell.lastGoodKey = null;
			lastGoodKey = null;
		}
		boolean isLastGood = key.equals(lastGoodKey);
		String lastGoodDigest = lastGoodKey == null ? "" : lastGoodKey.physicalKey().digest();
		double lastGoodUpper = lastGood == null || !lastGood.verifiedPresent
				? Double.NaN
				: lastGood.verifiedUpper;
		double regressionLimit = finiteNonNegative(lastGoodUpper)
				? lastGoodUpper
				: bestEligibleAlternativeUpper(group, key);
		if (!enforce) {
			/*
			 * Monitoring preserves the counterfactual safety state for a later rollout promotion, but it must be
			 * observational: every executable remains eligible and retains its point-cost ordering.
			 */
			return new Decision(State.MONITORING, true, isLastGood, envelope.point(), envelope, lastGoodDigest,
					lastGoodUpper, regressionLimit, "monitoring-only-" + entry.reason);
		}

		if (entry.state == State.BLOCKED || entry.state == State.QUARANTINED) {
			return new Decision(entry.state, false, isLastGood,
					Double.MAX_VALUE, envelope, lastGoodDigest, lastGoodUpper, regressionLimit,
					entry.reason);
		}
		if (isLastGood) {
			transition(entry, State.APPLYING, "last-good-retained");
			return new Decision(entry.state, true, true, envelope.upper(), envelope,
					lastGoodDigest, lastGoodUpper, regressionLimit, entry.reason);
		}
		if (lastGood != null) {
			double verifiedLower = !lastGood.verifiedPresent
					? lastGood.planned.lower()
					: lastGood.verifiedLower;
			if (envelope.upper() < verifiedLower) {
				transition(entry, State.APPLYING, "challenger-upper-below-last-good-lower");
				return new Decision(entry.state, true, false,
						envelope.upper(), envelope, lastGoodDigest, lastGoodUpper,
						regressionLimit,
						entry.reason);
			}
			transition(entry, State.MONITORING, "credible-interval-overlap-retain-last-good");
			return new Decision(entry.state, false, false,
					Double.MAX_VALUE, envelope, lastGoodDigest, lastGoodUpper,
					regressionLimit,
					entry.reason);
		}
		transition(entry, State.MONITORING, "no-last-good-robust-upper");
		return new Decision(entry.state, true, false, envelope.upper(), envelope,
				"", Double.NaN, regressionLimit, entry.reason);
	}

	private double bestEligibleAlternativeUpper(GroupKey group, LifecycleKey excluded) {
		double best = Double.POSITIVE_INFINITY;
		for (Map.Entry<LifecycleKey, Entry> stored : entries.entrySet()) {
			if (stored.getKey().equals(excluded) || !stored.getKey().group().equals(group)) {
				continue;
			}
			Entry candidate = stored.getValue();
			if (candidate.state != State.BLOCKED && candidate.state != State.QUARANTINED
					&& candidate.planned != null) {
				best = Math.min(best, candidate.planned.upper());
			}
		}
		return best;
	}

	/** Records one semantically valid completed execution. Returns false for inadmissible executions. */
	synchronized boolean observe(LogicalLearningKey logicalKey, PhysicalResidualKey physicalKey,
			LearningApplicability applicability, ObjectiveEnvelope planned, double actualObjective,
			boolean semanticallyValid, double regressionLimit, long epoch) {
		if (!validObservation(actualObjective, semanticallyValid, regressionLimit, epoch)) {
			return false;
		}
		LifecycleKey key = new LifecycleKey(logicalKey, physicalKey, applicability);
		Entry entry = entries.get(key);
		if (entry == null) {
			entry = admit(key, planned);
		}
		if (entry == null) {
			return false;
		}
		entry.planned = planned;
		GroupCell group = groups.computeIfAbsent(key.group(), ignored -> new GroupCell());
		return observe(key, entry, group, actualObjective, semanticallyValid, regressionLimit, epoch);
	}

	private boolean observe(LifecycleKey key, Entry entry, GroupCell group, double actualObjective,
			boolean semanticallyValid, double regressionLimit, long epoch) {
		if (!validObservation(actualObjective, semanticallyValid, regressionLimit, epoch)) {
			return false;
		}
		ObjectiveEnvelope planned = entry.planned;
		entry.lastEpoch = Math.max(entry.lastEpoch, epoch);
		LifecycleKey lastGoodKey = group.lastGoodKey;

		boolean exceedsPredictiveBound = actualObjective > planned.upper();
		boolean exceedsRegressionLimit = actualObjective > regressionLimit;
		if (exceedsPredictiveBound && exceedsRegressionLimit) {
			transition(entry, State.QUARANTINED, "predictive-and-regression-bound-exceeded");
			entry.lastGood = false;
			if (key.equals(lastGoodKey)) {
				group.lastGoodKey = null;
				group.lastGood = null;
			}
			return true;
		}
		if (exceedsRegressionLimit) {
			transition(entry, State.BLOCKED, "verified-regression-bound-exceeded");
			entry.lastGood = false;
			if (key.equals(lastGoodKey)) {
				group.lastGoodKey = null;
				group.lastGood = null;
			}
			return true;
		}

		group.history.append(key.physicalKey().digest());
		if (group.history.periodTwo() && lastGoodKey != null && !key.equals(lastGoodKey)) {
			transition(entry, State.BLOCKED, "period-two-freeze-last-good");
			entry.lastGood = false;
			return true;
		}

		double verifiedLower = Math.min(planned.lower(), actualObjective);
		double verifiedUpper = Math.max(planned.upper(), actualObjective);
		boolean verifiedChanged = !entry.verifiedPresent
				|| Double.compare(entry.verifiedLower, verifiedLower) != 0
				|| Double.compare(entry.verifiedPoint, actualObjective) != 0
				|| Double.compare(entry.verifiedUpper, verifiedUpper) != 0;
		entry.verifiedPresent = true;
		entry.verifiedLower = verifiedLower;
		entry.verifiedPoint = actualObjective;
		entry.verifiedUpper = verifiedUpper;
		if (lastGoodKey == null || key.equals(lastGoodKey) || entry.state == State.APPLYING) {
			promoteLastGood(key, entry, group);
		} else {
			transition(entry, State.MONITORING, "safe-monitoring-observation");
		}
		if (verifiedChanged) {
			revision++;
		}
		return true;
	}

	synchronized void markAllStale() {
		boolean changed = false;
		for (Entry entry : entries.values()) {
			if (entry.state != State.STALE || entry.lastGood) {
				entry.state = State.STALE;
				entry.reason = "epoch-change-monitoring";
				entry.lastGood = false;
				changed = true;
			}
		}
		if (!groups.isEmpty()) {
			groups.clear();
			changed = true;
		}
		if (changed) {
			generation++;
			revision++;
		}
	}

	synchronized long revision() {
		return revision;
	}

	synchronized int size() {
		return entries.size();
	}

	synchronized void clear() {
		if (entries.isEmpty() && groups.isEmpty()) {
			return;
		}
		entries.clear();
		groups.clear();
		generation++;
		revision++;
	}

	synchronized void writeTo(DataOutputStream out) throws IOException {
		out.writeLong(revision);
		out.writeInt(entries.size());
		for (Map.Entry<LifecycleKey, Entry> stored : entries.entrySet()) {
			stored.getKey().writeTo(out);
			stored.getValue().writeTo(out);
		}
		int historyCount = 0;
		for (GroupCell group : groups.values()) {
			historyCount += group.history.isEmpty() ? 0 : 1;
		}
		out.writeInt(historyCount);
		for (Map.Entry<GroupKey, GroupCell> stored : groups.entrySet()) {
			if (!stored.getValue().history.isEmpty()) {
				stored.getKey().writeTo(out);
				stored.getValue().history.writeTo(out);
			}
		}
	}

	static PlanLifecycleStore readFrom(DataInputStream in, int maximumEntries) throws IOException {
		PlanLifecycleStore result = new PlanLifecycleStore(maximumEntries);
		result.revision = Math.max(0L, in.readLong());
		int count = boundedCount(in.readInt(), maximumEntries * MAX_PERSISTED_ENTRIES_MULTIPLIER,
				"lifecycle entry");
		for (int index = 0; index < count; index++) {
			LifecycleKey key = LifecycleKey.readFrom(in);
			Entry entry = Entry.readFrom(in);
			result.entries.put(key, entry);
			if (entry.lastGood) {
				GroupCell group = result.groups.computeIfAbsent(key.group(), ignored -> new GroupCell());
				group.lastGoodKey = key;
				group.lastGood = entry;
			}
		}
		int histories = boundedCount(in.readInt(), maximumEntries * MAX_PERSISTED_ENTRIES_MULTIPLIER,
				"lifecycle history");
		for (int index = 0; index < histories; index++) {
			result.groups.computeIfAbsent(GroupKey.readFrom(in), ignored -> new GroupCell()).history = SelectionHistory
					.readFrom(in);
		}
		result.evictToBound();
		return result;
	}

	private Entry admit(LifecycleKey key, ObjectiveEnvelope planned) {
		if (entries.size() >= maximumEntries && !evictOneOrdinary()) {
			return null;
		}
		Entry entry = new Entry(State.MONITORING, planned, null, false, 0L, "monitoring");
		entries.put(key, entry);
		revision++;
		return entry;
	}

	private boolean evictOneOrdinary() {
		var iterator = entries.entrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<LifecycleKey, Entry> candidate = iterator.next();
			Entry entry = candidate.getValue();
			if (entry.leases == 0 && !entry.lastGood && entry.state != State.QUARANTINED
					&& (entry.state == State.STALE || entry.state == State.MONITORING)) {
				GroupKey removedGroup = candidate.getKey().group();
				iterator.remove();
				boolean groupRetained = false;
				for (LifecycleKey retained : entries.keySet()) {
					if (retained.group().equals(removedGroup)) {
						groupRetained = true;
						break;
					}
				}
				if (!groupRetained) {
					groups.remove(removedGroup);
				}
				revision++;
				return true;
			}
		}
		return false;
	}

	private void evictToBound() {
		while (entries.size() > maximumEntries && evictOneOrdinary()) {
			// Evict ordinary records oldest-first; protected records may keep a restored store above its soft bound.
		}
	}

	private void promoteLastGood(LifecycleKey key, Entry entry, GroupCell group) {
		LifecycleKey priorKey = group.lastGoodKey;
		Entry prior = group.lastGood;
		group.lastGoodKey = key;
		group.lastGood = entry;
		if (priorKey != null && !priorKey.equals(key)) {
			if (prior != null) {
				prior.lastGood = false;
				transition(prior, State.MONITORING, "superseded-by-verified-last-good");
			}
		}
		boolean markerChanged = !entry.lastGood;
		entry.lastGood = true;
		transition(entry, State.APPLYING, "verified-last-good");
		if (markerChanged || !key.equals(priorKey)) {
			revision++;
		}
	}

	private void transition(Entry entry, State state, String reason) {
		if (entry.state != state || !Objects.equals(entry.reason, reason)) {
			entry.state = state;
			entry.reason = reason;
			revision++;
		}
	}

	private static int boundedCount(int value, int maximum, String label) throws IOException {
		if (value < 0 || value > maximum) {
			throw new IOException("Invalid " + label + " count: " + value);
		}
		return value;
	}

	private static boolean finiteNonNegative(double value) {
		return Double.isFinite(value) && value >= 0.0d;
	}

	private static boolean validObservation(double actualObjective, boolean semanticallyValid,
			double regressionLimit, long epoch) {
		return semanticallyValid && finiteNonNegative(actualObjective) && epoch >= 0L
				&& (finiteNonNegative(regressionLimit) || regressionLimit == Double.POSITIVE_INFINITY);
	}

	private record LifecycleKey(LogicalLearningKey logicalKey, PhysicalResidualKey physicalKey,
			LearningApplicability applicability) {
		private LifecycleKey {
			Objects.requireNonNull(logicalKey, "logical key");
			Objects.requireNonNull(physicalKey, "physical key");
			Objects.requireNonNull(applicability, "learning applicability");
		}

		private GroupKey group() {
			return new GroupKey(logicalKey, applicability);
		}

		private void writeTo(DataOutputStream out) throws IOException {
			logicalKey.writeTo(out);
			physicalKey.writeTo(out);
			applicability.writeTo(out);
		}

		private static LifecycleKey readFrom(DataInputStream in) throws IOException {
			return new LifecycleKey(LogicalLearningKey.readFrom(in), PhysicalResidualKey.readFrom(in),
					LearningApplicability.readFrom(in));
		}
	}

	private record GroupKey(LogicalLearningKey logicalKey, LearningApplicability applicability) {
		private void writeTo(DataOutputStream out) throws IOException {
			logicalKey.writeTo(out);
			applicability.writeTo(out);
		}

		private static GroupKey readFrom(DataInputStream in) throws IOException {
			return new GroupKey(LogicalLearningKey.readFrom(in), LearningApplicability.readFrom(in));
		}
	}

	private static final class GroupCell {
		private LifecycleKey lastGoodKey;
		private Entry lastGood;
		private SelectionHistory history = new SelectionHistory();
	}

	private static final class Entry {
		private State state;
		private ObjectiveEnvelope planned;
		private boolean verifiedPresent;
		private double verifiedLower;
		private double verifiedPoint;
		private double verifiedUpper;
		private boolean lastGood;
		private long lastEpoch;
		private String reason;
		private int leases;

		private Entry(State state, ObjectiveEnvelope planned, ObjectiveEnvelope verified, boolean lastGood,
				long lastEpoch, String reason) {
			this.state = state;
			this.planned = planned;
			if (verified != null) {
				verifiedPresent = true;
				verifiedLower = verified.lower();
				verifiedPoint = verified.point();
				verifiedUpper = verified.upper();
			}
			this.lastGood = lastGood;
			this.lastEpoch = lastEpoch;
			this.reason = reason;
		}

		private void writeTo(DataOutputStream out) throws IOException {
			out.writeByte(state.ordinal());
			planned.writeTo(out);
			out.writeBoolean(verifiedPresent);
			if (verifiedPresent) {
				out.writeDouble(verifiedLower);
				out.writeDouble(verifiedPoint);
				out.writeDouble(verifiedUpper);
			}
			out.writeBoolean(lastGood);
			out.writeLong(lastEpoch);
			LearningKeyCodec.writeString(out, reason);
		}

		private static Entry readFrom(DataInputStream in) throws IOException {
			int ordinal = Byte.toUnsignedInt(in.readByte());
			if (ordinal >= State.values().length) {
				throw new IOException("Invalid lifecycle state: " + ordinal);
			}
			ObjectiveEnvelope planned = ObjectiveEnvelope.readFrom(in);
			ObjectiveEnvelope verified = in.readBoolean() ? ObjectiveEnvelope.readFrom(in) : null;
			boolean lastGood = in.readBoolean();
			long lastEpoch = in.readLong();
			if (lastEpoch < 0L) {
				throw new IOException("Invalid lifecycle epoch: " + lastEpoch);
			}
			return new Entry(State.values()[ordinal], planned, verified, lastGood, lastEpoch,
					LearningKeyCodec.readString(in, "lifecycle reason"));
		}
	}

	private static final class SelectionHistory {
		private final String[] physicalDigests = new String[4];
		private int size;

		private void append(String physicalDigest) {
			if (size < physicalDigests.length) {
				physicalDigests[size++] = physicalDigest;
				return;
			}
			System.arraycopy(physicalDigests, 1, physicalDigests, 0, physicalDigests.length - 1);
			physicalDigests[physicalDigests.length - 1] = physicalDigest;
		}

		private boolean periodTwo() {
			return size == 4
					&& !Objects.equals(physicalDigests[0], physicalDigests[1])
					&& Objects.equals(physicalDigests[0], physicalDigests[2])
					&& Objects.equals(physicalDigests[1], physicalDigests[3]);
		}

		private boolean isEmpty() {
			return size == 0;
		}

		private void writeTo(DataOutputStream out) throws IOException {
			out.writeByte(size);
			for (int index = 0; index < size; index++) {
				LearningKeyCodec.writeString(out, physicalDigests[index]);
			}
		}

		private static SelectionHistory readFrom(DataInputStream in) throws IOException {
			SelectionHistory result = new SelectionHistory();
			int count = Byte.toUnsignedInt(in.readByte());
			if (count > result.physicalDigests.length) {
				throw new IOException("Invalid lifecycle selection history size: " + count);
			}
			for (int index = 0; index < count; index++) {
				result.physicalDigests[result.size++] = LearningKeyCodec.readString(in,
						"lifecycle physical digest");
			}
			return result;
		}
	}
}
